option.value:
apply plugin: 'com.android.application'
apply plugin: 'org.jetbrains.kotlin.kapt'
apply plugin: 'org.jetbrains.kotlin.android'
apply plugin: 'com.google.firebase.crashlytics'
apply plugin: 'com.google.gms.google-services'

def WEATHER_API_KEY = ""
def KEYSTORE_FILE   = ""
def KEYSTORE_PASS   = ""
def KEY_ALIAS       = ""
def KEY_PASS        = ""

Properties properties = new Properties()
def localPropertiesFile = rootProject.file("local.properties")
if (localPropertiesFile.exists()) {
    properties.load(new FileInputStream(localPropertiesFile))
    WEATHER_API_KEY = properties.getProperty("WEATHER_API_KEY", "")
    KEYSTORE_FILE   = properties.getProperty("KEYSTORE_FILE", "")
    KEYSTORE_PASS   = properties.getProperty("KEYSTORE_PASS", "")
    KEY_ALIAS       = properties.getProperty("KEY_ALIAS", "")
    KEY_PASS        = properties.getProperty("KEY_PASS", "")
}

android {
    namespace 'com.adjaba'

    compileSdkVersion 36
    defaultConfig {
        applicationId "com.adjaba"
        minSdkVersion 21
        targetSdkVersion 34
        versionCode 3
        versionName "1.0.3"
        vectorDrawables.useSupportLibrary = true
        testInstrumentationRunner "android.support.test.runner.AndroidJUnitRunner"
        multiDexEnabled true

        buildConfigField "String", "WEATHER_API_KEY", "\"${WEATHER_API_KEY}\""
    }

    signingConfigs {
        release {
            storeFile     KEYSTORE_FILE ? file(KEYSTORE_FILE) : null
            storePassword KEYSTORE_PASS
            keyAlias      KEY_ALIAS
            keyPassword   KEY_PASS
        }
    }

    buildTypes {
        release {
            signingConfig signingConfigs.release
            minifyEnabled true
            proguardFiles getDefaultProguardFile('proguard-android.txt'), 'proguard-rules.pro'
        }
    }

    applicationVariants.all { variant ->
        variant.outputs.all { output ->
            if (variant.buildType.name == "release") {
                outputFileName = "ADPLAYER-v${variant.versionName}-release.apk"
            }
        }
    }
    // Temporary fix until alpha10
    packagingOptions {
        exclude 'META-INF/proguard/androidx-annotations.pro'
    }
    aaptOptions {
        noCompress "tflite"  // Your model's file extension: "tflite", "lite", etc.
    }
    compileOptions {
        sourceCompatibility JavaVersion.VERSION_17
        targetCompatibility JavaVersion.VERSION_17
    }
    kotlinOptions {
        jvmTarget = '17'
    }

    lintOptions {
        abortOnError false
        checkReleaseBuilds false
    }

    buildFeatures {
        buildConfig = true
    }
}

dependencies {
    implementation fileTree(dir: 'libs', include: ['*.jar'])
    implementation 'com.google.android.material:material:1.13.0' // أو آخر نسخة متاحة عندك

    // AndroidX core
    implementation 'androidx.appcompat:appcompat:1.5.1'
    implementation 'androidx.constraintlayout:constraintlayout:2.1.4'
    implementation 'androidx.multidex:multidex:2.0.1'
    implementation 'com.google.android.material:material:1.11.0'
    implementation 'androidx.activity:activity:1.11.0'
    testImplementation 'junit:junit:4.13.2'
    androidTestImplementation 'androidx.test:runner:1.5.2'
    androidTestImplementation 'androidx.test.espresso:espresso-core:3.5.1'

    // Retrofit + GSON + OkHttp
    implementation 'com.squareup.retrofit2:retrofit:2.9.0'
    implementation 'com.squareup.retrofit2:converter-gson:2.9.0'
    implementation 'com.squareup.retrofit2:adapter-rxjava:2.9.0'
    implementation 'com.squareup.okhttp3:okhttp:5.0.0-alpha.3'
    implementation 'com.squareup.okhttp3:logging-interceptor:5.0.0-alpha.3'
    implementation 'com.google.code.gson:gson:2.10'

    // RxJava
    implementation "io.reactivex.rxjava2:rxjava:2.2.21"
    implementation "io.reactivex.rxjava2:rxandroid:2.1.1"
    implementation "androidx.room:room-rxjava2:2.6.1"

    // ExoPlayer
    implementation 'com.google.android.exoplayer:exoplayer:2.19.1'

    // Glide
    implementation 'com.github.bumptech.glide:glide:4.14.2'
    kapt 'com.github.bumptech.glide:compiler:4.14.2'

    //logo animation
    implementation "com.airbnb.android:lottie:6.0.0"

    //shimmer animation
    implementation 'com.facebook.shimmer:shimmer:0.5.0'


    // QR Code
    implementation 'com.github.androidmads:QRGenerator:1.0.1'
    implementation 'com.google.zxing:core:3.5.1'


    implementation "com.google.android.exoplayer:exoplayer:2.19.1"
    implementation "com.google.android.exoplayer:exoplayer-ui:2.19.1"


    // Room components
    implementation "androidx.room:room-runtime:2.6.1"
    annotationProcessor "androidx.room:room-compiler:2.6.1" // لـ Java

// Optional: لو هتستخدم RxJava أو Coroutines
    implementation "androidx.room:room-ktx:2.6.1"
    kapt "androidx.room:room-compiler:2.6.1"
    implementation "androidx.security:security-crypto:1.1.0-alpha06"

    // WorkManager for offline impression retry
    implementation "androidx.work:work-runtime:2.9.0"

    // LocalBroadcastManager for playlist sync notifications
    implementation "androidx.localbroadcastmanager:localbroadcastmanager:1.1.0"

    // MQTT for real-time demographic-based ad switching
    implementation 'org.eclipse.paho:org.eclipse.paho.client.mqttv3:1.2.5'
    implementation 'androidx.legacy:legacy-support-v4:1.0.0'

    implementation "com.airbnb.android:lottie:6.1.0"


}

