    public static String downloadFileToInternalStorage(Context context, String fileUrl, String fileName, String token) {
        OkHttpClient client = new OkHttpClient();
        Request.Builder builder = new Request.Builder().url(fileUrl);
        if (token != null) builder.addHeader("Authorization", "Bearer " + token);
        try (okhttp3.Response response = client.newCall(builder.build()).execute()) {
            if (response.isSuccessful() && response.body() != null) {
                InputStream inputStream = response.body().byteStream();
                File file = new File(context.getFilesDir(), fileName);
                FileOutputStream outputStream = new FileOutputStream(file);
                byte[] buffer = new byte[4096];
                int bytesRead;
                while ((bytesRead = inputStream.read(buffer)) != -1) outputStream.write(buffer, 0, bytesRead);
                outputStream.close();
                inputStream.close();
                return file.getAbsolutePath();
            }
        } catch (IOException e) { e.printStackTrace(); }
        return null;
    }

    public static String downloadFileToInternalStorage(Context context, String fileUrl, String fileName) {
        OkHttpClient client = new OkHttpClient();

        Request request = new Request.Builder()
                .url(fileUrl)
                .build();

        try (okhttp3.Response response = client.newCall(request).execute()) {
            if (response.isSuccessful()) {
                InputStream inputStream = response.body().byteStream();
                File file = new File(context.getFilesDir(), fileName);
                FileOutputStream outputStream = new FileOutputStream(file);
                byte[] buffer = new byte[4096];
                int bytesRead;

                while ((bytesRead = inputStream.read(buffer)) != -1) {
                    outputStream.write(buffer, 0, bytesRead);
                }

                outputStream.close();
                inputStream.close();

                return file.getAbsolutePath();
            }
        } catch (IOException e) {
            e.printStackTrace();
        }

        return null;
    }

    public static String getFileExtensionFromUrl(String url) {
        if (url != null) {
            return MimeTypeMap.getFileExtensionFromUrl(url);
        }
        return null;
    }

    public static boolean isImage(String url) {
        String ext = getFileExtensionFromUrl(url);
        return ext != null && (ext.equalsIgnoreCase("jpg") || ext.equalsIgnoreCase("jpeg") ||
                ext.equalsIgnoreCase("png") || ext.equalsIgnoreCase("gif") ||
                ext.equalsIgnoreCase("bmp") || ext.equalsIgnoreCase("webp"));
    }

    public static boolean isVideo(String url) {
        String ext = getFileExtensionFromUrl(url);
        return ext != null && (ext.equalsIgnoreCase("mp4") || ext.equalsIgnoreCase("mkv") ||
                ext.equalsIgnoreCase("3gp") || ext.equalsIgnoreCase("avi") ||
                ext.equalsIgnoreCase("mov"));
    }

    public void setNoAdsLogoAnimation() {
        handlerLogo = new Handler();
        runnableLogo = new Runnable() {
            @Override
            public void run() {
                float x = noAdsLogo.getX() + dx;
                float y = noAdsLogo.getY() + dy;

                // حدود الشاشة
                int screenWidth = ((View) noAdsLogo.getParent()).getWidth();
                int screenHeight = ((View) noAdsLogo.getParent()).getHeight();

                // لو الوجو خبط في اليمين أو الشمال
                if (x <= 0 || x + noAdsLogo.getWidth() >= screenWidth) {
                    dx = -dx;
                }

                // لو الوجو خبط فوق أو تحت
                if (y <= 0 || y + noAdsLogo.getHeight() >= screenHeight) {
                    dy = -dy;
                }

                noAdsLogo.setX(x);
                noAdsLogo.setY(y);

                handlerLogo.postDelayed(this, 16); // ~60 FPS
            }
        };
        noAdsLogo.post(() -> handlerLogo.post(runnableLogo));
    }

    /**
     * Slide the new view in from the right while fading out the old view to the left.
     * Works at any screen size — offset is proportional to display density.
     */
    private void slideTransition(final View showView, final View hideView) {
        float offsetPx = getResources().getDisplayMetrics().density * 60; // 60dp in px

        if (hideView != null && hideView.getVisibility() == View.VISIBLE) {
            hideView.animate()
                    .alpha(0f)
                    .translationXBy(-offsetPx)
                    .setDuration(450)
                    .setInterpolator(new AccelerateInterpolator())
                    .withEndAction(() -> {
                        hideView.setVisibility(View.GONE);
                        hideView.setTranslationX(0f);
                        hideView.setAlpha(1f);
                    })
                    .start();
        }

        showView.setAlpha(0f);
        showView.setTranslationX(offsetPx);
        showView.setVisibility(View.VISIBLE);
        showView.animate()
                .alpha(1f)
                .translationX(0f)
                .setDuration(450)
                .setInterpolator(new DecelerateInterpolator())
                .start();
    }

    /** Simple crossfade kept for video player internal transitions. */
    private void crossfade(final View showView, final View hideView, long duration) {
        if (hideView != null) {
            hideView.animate()
                    .alpha(0f)
                    .setDuration(duration)
                    .withEndAction(() -> hideView.setVisibility(View.GONE))
                    .start();
        }
        showView.setAlpha(0f);
        showView.setVisibility(View.VISIBLE);
        showView.animate()
                .alpha(1f)
                .setDuration(duration)
                .start();
    }

    /**
     * Updates debug overlay with current playback status.
     * Shows: current media type, index, ads loaded, etc.
     * TODO: Remove this before production release
     */
    private void updateDebugText(String message) {
        String timestamp = new SimpleDateFormat("HH:mm:ss", Locale.getDefault()).format(new Date());
        String fullMsg = timestamp + " | " + message;

        // Always log to logcat
        android.util.Log.e("AdvertWatching", " " + fullMsg);

        // Also try to update overlay if it exists
        if (debugOverlay != null) {
            runOnUiThread(() -> {
                try {
                    debugOverlay.setText(fullMsg);
                    android.util.Log.e("AdvertWatching", " Overlay updated: " + fullMsg);
                } catch (Exception e) {
                    android.util.Log.e("AdvertWatching", " ERROR updating overlay: " + e.getMessage());
                }
            });
        } else {
            android.util.Log.e("AdvertWatching", " WARNING: debugOverlay is NULL, can't update UI");
        }
    }
}

package com.adjaba.content;

import android.content.Context;
import android.util.AttributeSet;
import android.webkit.WebChromeClient;
import android.webkit.WebSettings;
import android.webkit.WebView;
import android.webkit.WebViewClient;
import android.graphics.Color;

/**
 * Secure WebView for displaying HTML/Web content in digital signage
 * Supports: HTML widgets, dashboards, Google Slides, custom web pages
 * 
 * Security:
 * - JavaScript enabled but sandboxed
 * - File access disabled
 * - Geolocation disabled
 * - No camera/microphone access
 */
public class SecureSignageWebView extends WebView {

    private WebViewLoadListener loadListener;
    private String currentUrl;

    public interface WebViewLoadListener {
        void onPageLoaded(String url);
        void onPageError(String url, int errorCode, String description);
        void onProgressChanged(int progress);
    }

    public SecureSignageWebView(Context context) {
        super(context);
        init();
    }

    public SecureSignageWebView(Context context, AttributeSet attrs) {
        super(context, attrs);
        init();
    }

    private void init() {
        // Configure WebView settings for digital signage
        WebSettings settings = getSettings();

        // Enable JavaScript (required for most modern web content)
        settings.setJavaScriptEnabled(true);

        // Enable DOM storage for web apps
        settings.setDomStorageEnabled(true);

        // Enable zoom controls (may be useful for debugging)
        settings.setBuiltInZoomControls(false);
        settings.setSupportZoom(false);

        // Set cache mode for offline support
        settings.setCacheMode(WebSettings.LOAD_DEFAULT);

        // Enable hardware acceleration
        setLayerType(LAYER_TYPE_HARDWARE, null);

        // Security settings
        settings.setAllowFileAccess(false); // Disable file access
        settings.setAllowContentAccess(false); // Disable content provider access
        settings.setGeolocationEnabled(false); // Disable geolocation
        settings.setMediaPlaybackRequiresUserGesture(false); // Allow autoplay

        /

/ Mixed content (HTTP in HTTPS)
        settings.setMixedContentMode(WebSettings.MIXED_CONTENT_COMPATIBILITY_MODE);

        // Display settings
        settings.setLoadWithOverviewMode(true);
        settings.setUseWideViewPort(true);
        settings.setLayoutAlgorithm(WebSettings.LayoutAlgorithm.TEXT_AUTOSIZING);

        // Background color
        setBackgroundColor(Color.TRANSPARENT);

        // Set WebViewClient to handle page navigation
        setWebViewClient(new SecureWebViewClient());

        // Set WebChromeClient to handle JavaScript dialogs and progress
        setWebChromeClient(new SecureWebChromeClient());
    }

    public void setLoadListener(WebViewLoadListener listener) {
        this.loadListener = listener;
    }

    /**
     * Load URL with error handling
     */
    public void loadUrlSafe(String url) {
        this.currentUrl = url;
        if (url != null && !url.isEmpty()) {
            loadUrl(url);
        }
    }

    /**
     * Load HTML content directly
     */
    public void loadHtmlContent(String htmlContent, String baseUrl) {
        loadDataWithBaseURL(baseUrl, htmlContent, "text/html", "UTF-8", null);
    }

    /**
     * Reload current page
     */
    public void reloadPage() {
        if (currentUrl != null) {
            loadUrl(currentUrl);
        } else {
            reload();
        }
    }

    /**
     * Clear cache and cookies
     */
    public void clearWebViewData() {
        clearCache(true);
        clearHistory();
    }

    /**
     * Execute JavaScript in the web page
     */
    public void executeJavaScript(String script) {
        if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.KITKAT) {
            evaluateJavascript(script, null);
        } else {
            loadUrl("javascript:" + script);
        }
    }

    /**
     * Custom WebViewClient for security and navigation control
     */
    private class SecureWebViewClient extends WebViewClient {

        @Override
        public void onPageFinished(WebView view, String url) {
            super.onPageFinished(view, url);
            if (loadListener != null) {
                loadListener.onPageLoaded(url);
            }
        }

        @Override
        public void onReceivedError(WebView view, int errorCode, String description, String failingUrl) {
            super.onReceivedError(view, errorCode, description, failingUrl);
            if (loadListener != null) {
                loadListener.onPageError(failingUrl, errorCode, description);
            }
        }

        @Override
        public boolean shouldOverrideUrlLoading(WebView view, String url) {
            // Allow all HTTPS and HTTP URLs
            // Block file:// and other protocols for security
            if (url.startsWith("http://") || url.startsWith("https://")) {
                view.loadUrl(url);
                return false;
            }
            // Block other protocols
            return true;
        }
    }

    /**
     * Custom WebChromeClient for progress tracking
     */
    private class SecureWebChromeClient extends WebChromeClient {

        @Override
        public void onProgressChanged(WebView view, int newProgress) {
            super.onProgressChanged(view, newProgress);
            if (loadListener != null) {
                loadListener.onProgressChanged(newProgress);
            }
        }

        @Override
        public boolean onJsAlert(WebView view, String url, String message, android.webkit.JsResult result) {
            // Suppress JavaScript alerts in digital signage
            result.confirm();
            return true;
        }

        @Override
        public boolean onJsConfirm(WebView view, String url, String message, android.webkit.JsResult result) {
            // Auto-confirm JavaScript confirms
            result.confirm();
            return true;
        }
    }

    /**
     * Cleanup resources
     */
    public void cleanup() {
        stopLoading();
        clearWebViewData();
        removeAllViews();
        destroy();
    }
}

