                mainHandler.post(() -> listener.onError("Instagram API error: " + e.getMessage()));
            }
        });
    }

    /**
     * Fetch posts from multiple platforms
     */
    public void fetchMixedFeed(String hashtag, SocialPlatform[] platforms, int maxResults, SocialFeedListener listener) {
        executor.execute(() -> {
            try {
                List<SocialPost> allPosts = new ArrayList<>();

                for (SocialPlatform platform : platforms) {
                    switch (platform) {
                        case TWITTER:
                            List<SocialPost> tweets = createSampleTwitterPosts(hashtag, maxResults / platforms.length);
                            allPosts.addAll(tweets);
                            break;
                        case INSTAGRAM:
                            List<SocialPost> igPosts = createSampleInstagramPosts(hashtag, maxResults / platforms.length);
                            allPosts.addAll(igPosts);
                            break;
                        // Add Facebook, LinkedIn as needed
                    }
                }

                // Sort by timestamp (newest first)
                allPosts.sort((p1, p2) -> p2.timestamp.compareTo(p1.timestamp));

                final List<SocialPost> finalPosts = allPosts;
                mainHandler.post(() -> listener.onPostsLoaded(finalPosts));

            } catch (Exception e) {
                Log.e(TAG, "Error fetching mixed feed", e);
                mainHandler.post(() -> listener.onError("Mixed feed error: " + e.getMessage()));
            }
        });
    }

    /**
     * Make HTTP API call (helper method)
     */
    private JSONObject makeApiCall(String apiUrl, String bearerToken) throws Exception {
        URL url = new URL(apiUrl);
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod("GET");
        conn.setRequestProperty("Authorization", "Bearer " + bearerToken);
        conn.setRequestProperty("Content-Type", "application/json");
        conn.setConnectTimeout(15000);
        conn.setReadTimeout(15000);

        int responseCode = conn.getResponseCode();
        if (responseCode == 200) {
            BufferedReader reader = new BufferedReader(new InputStreamReader(conn.getInputStream()));
            StringBuilder response = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                response.append(line);
            }
            reader.close();
            return new JSONObject(response.toString());
        } else {
            throw new Exception("API returned error code: " + responseCode);
        }
    }

    /**
     * Create sample Twitter posts for demo/testing
     */
    private List<SocialPost> createSampleTwitterPosts(String hashtag, int count) {
        List<SocialPost> posts = new ArrayList<>();

        for (int i = 0; i < count; i++) {
            SocialPost post = new SocialPost(SocialPlatform.TWITTER);
            post.id = "tweet_" + i;
            post.username = "@user" + (i + 1);
            post.userDisplayName = "Demo User " + (i + 1);
            post.text = "Amazing event! #" + hashtag + " - Sample tweet " + (i + 1);
            post.likes = (int) (Math.random() * 1000);
            post.retweets = (int) (Math.random() * 100);
            post.comments = (int) (Math.random() * 50);
            post.timestamp = new Date(System.currentTimeMillis() - (i * 60000)); // Minutes ago
            posts.add(post);
        }

        return posts;
    }

    /**
     * Create sample Instagram posts for demo/testing
     */
    private List<SocialPost> createSampleInstagramPosts(String hashtag, int count) {
        List<SocialPost> posts = new ArrayList<>();

        for (int i = 0; i < count; i++) {
            SocialPost post = new SocialPost(SocialPlatform.INSTAGRAM);
            post.id = "ig_" + i;
            post.username = "user" + (i + 1);
            post.userDisplayName = "Instagram User " + (i + 1);
            post.text = "Love this! #" + hashtag;
            post.likes = (int) (Math.random() * 5000);
            post.comments = (int) (Math.random() * 500);
            post.timestamp = new Date(System.currentTimeMillis() - (i * 120000)); // Minutes ago
            posts.add(post);
        }

        return posts;
    }

    /**
     * Shutdown executor
     */
    public void shutdown() {
        if (executor != null && !executor.isShutdown()) {
            executor.shutdown();
        }
    }
}

package com.adjaba.streaming;

import android.content.Context;
import android.net.Uri;
import android.util.Log;

import com.google.android.exoplayer2.ExoPlayer;
import com.google.android.exoplayer2.MediaItem;
import com.google.android.exoplayer2.PlaybackException;
import com.google.android.exoplayer2.Player;
import com.google.android.exoplayer2.source.MediaSource;
import com.google.android.exoplayer2.source.ProgressiveMediaSource;
import com.google.android.exoplayer2.source.dash.DashMediaSource;
import com.google.android.exoplayer2.source.hls.HlsMediaSource;
import com.google.android.exoplayer2.ui.PlayerView;
import com.google.android.exoplayer2.upstream.DefaultDataSource;
import com.google.android.exoplayer2.upstream.DefaultHttpDataSource;

/**
 * Live Stream Manager for Digital Signage
 * Supports: HLS, DASH, RTSP, and progressive HTTP streams
 * 
 * Use Cases:
 * - Live TV channels
 * - Security camera feeds
 * - YouTube Live streams
 * - Corporate webcasts
 * - Event broadcasts
 */
public class LiveStreamManager {

    private static final String TAG = "LiveStreamManager";

    public enum StreamType {
        HLS,        // HTTP Live Streaming (.m3u8)
        DASH,       // Dynamic Adaptive Streaming over HTTP (.mpd)
        RTSP,       // Real Time Streaming Protocol
        HTTP        // Progressive download (MP4, etc.)
    }

    public enum StreamQuality {
        AUTO,       // Adaptive bitrate
        LOW,        // 480p or lower
        MEDIUM,     // 720p
        HIGH,       // 1080p
        ULTRA       // 4K
    }

    private ExoPlayer player;
    private PlayerView playerView;
    private Context context;
    private StreamListener listener;
    private String currentStreamUrl;
    private StreamType currentStreamType;
    private boolean isLive;

    public interface StreamListener {
        void onStreamReady();
        void onStreamPlaying();
        void onStreamBuffering();
        void onStreamError(String error);
        void onStreamEnded();
    }

    public LiveStreamManager(Context context, PlayerView playerView) {
        this.context = context;
        this.playerView = playerView;
        initializePlayer();
    }

    private void initializePlayer() {
        player = new ExoPlayer.Builder(context)
                .build();

        playerView.setPlayer(player);
        playerView.setUseController(false); // Hide controls for digital signage

        // Add listener for playback events
        player.addListener(new Player.Listener() {
            @Override
            public void onPlaybackStateChanged(int state) {
                switch (state) {
                    case Player.STATE_READY:
                        if (listener != null) listener.onStreamReady();
                        break;
                    case Player.STATE_BUFFERING:
                        if (listener != null) listener.onStreamBuffering();
                        break;
                    case Player.STATE_ENDED:
                        if (listener != null) listener.onStreamEnded();
                        break;
                }
            }

            @Override
            public void onIsPlayingChanged(boolean isPlaying) {
                if (isPlaying && listener != null) {
                    listener.onStreamPlaying();
                }
            }

            @Override
            public void onPlayerError(PlaybackException error) {
                String errorMsg = "Stream error: " + error.getMessage();
                Log.e(TAG, errorMsg, error);
                if (listener != null) {
                    listener.onStreamError(errorMsg);
                }
            }
        });
    }

    public void setStreamListener(StreamListener listener) {
        this.listener = listener;
    }

    /**
     * Detect stream type from URL
     */
    private StreamType detectStreamType(String url) {
        if (url == null) return StreamType.HTTP;

        String lowerUrl = url.toLowerCase();
        if (lowerUrl.contains(".m3u8")) {
            return StreamType.HLS;
        } else if (lowerUrl.contains(".mpd")) {
            return StreamType.DASH;
        } else if (lowerUrl.startsWith("rtsp://")) {
            return StreamType.RTSP;
        } else {
            return StreamType.HTTP;
        }
    }

    /**
     * Play live stream from URL
     */
    public void playStream(String streamUrl) {
        playStream(streamUrl, detectStreamType(streamUrl));
    }

    /**
     * Play live stream with explicit type
     */
    public void playStream(String streamUrl, StreamType streamType) {
        this.currentStreamUrl = streamUrl;
        this.currentStreamType = streamType;
        this.isLive = true;

        Log.i(TAG, "Playing stream: " + streamUrl + " (Type: " + streamType + ")");

        try {
            // Create appropriate media source based on stream type
            MediaSource mediaSource = createMediaSource(streamUrl, streamType);

            // Prepare and play
            player.setMediaSource(mediaSource);
            player.prepare();
            player.setPlayWhenReady(true);

        } catch (Exception e) {
            Log.e(TAG, "Error playing stream", e);
            if (listener != null) {
                listener.onStreamError("Failed to play stream: " + e.getMessage());
            }
        }
    }

    /**
     * Create MediaSource based on stream type
     */
    private MediaSource createMediaSource(String url, StreamType streamType) {
        // Create data source factory
        DefaultHttpDataSource.Factory httpDataSourceFactory = 
                new DefaultHttpDataSource.Factory()
                        .setAllowCrossProtocolRedirects(true)
                        .setConnectTimeoutMs(30000)
                        .setReadTimeoutMs(30000);

        DefaultDataSource.Factory dataSourceFactory = 
                new DefaultDataSource.Factory(context, httpDataSourceFactory);

        MediaItem mediaItem = MediaItem.fromUri(Uri.parse(url));

        switch (streamType) {
            case HLS:
                return new HlsMediaSource.Factory(dataSourceFactory)
                        .createMediaSource(mediaItem);

            case DASH:
                return new DashMediaSource.Factory(dataSourceFactory)
                        .createMediaSource(mediaItem);

            case RTSP:
            case HTTP:
            default:
                return new ProgressiveMediaSource.Factory(dataSourceFactory)
                        .createMediaSource(mediaItem);
        }
    }

    /**
     * Play RTSP stream (security cameras, etc.)
     */
    public void playRtspStream(String rtspUrl) {
        playStream(rtspUrl, StreamType.RTSP);
    }

    /**
     * Play HLS stream (.m3u8)
     */
    public void playHlsStream(String hlsUrl) {
        playStream(hlsUrl, StreamType.HLS);
    }

    /**
     * Play DASH stream (.mpd)
     */
    public void playDashStream(String dashUrl) {
        playStream(dashUrl, StreamType.DASH);
    }

    /**
     * Play YouTube Live stream
     * Note: Requires extracting HLS URL from YouTube
     */
    public void playYouTubeLive(String youtubeUrl) {
        // TODO: Implement YouTube URL extraction
        Log.w(TAG, "YouTube Live support requires URL extraction - implement separately");
    }

    /**
     * Stop stream
     */
    public void stop() {
        if (player != null) {
            player.stop();
            player.clearMediaItems();
        }
        isLive = false;
    }

    /**
     * Pause stream (if supported)
     */
    public void pause() {
        if (player != null && !isWindowLive()) {
            player.pause();
        }
    }

    /**
     * Resume stream
     */
    public void resume() {
        if (player != null) {
            player.play();
        }
    }

    /**
     * Check if current stream is live
     */
    public boolean isLive() {
        return isLive;
    }

    /**
     * Check if current window is live
     */
    private boolean isWindowLive() {
        if (player != null) {
            return player.isCurrentMediaItemLive();
        }
        return false;
    }

    /**
     * Get current stream URL
     */
    public String getCurrentStreamUrl() {
        return currentStreamUrl;
    }

    /**
     * Get current stream type
     */
    public StreamType getCurrentStreamType() {
        return currentStreamType;
    }

    /**
     * Check if stream is playing
     */
    public boolean isPlaying() {
        return player != null && player.isPlaying();
    }

    /**
     * Set volume (0.0 to 1.0)
     */
    public void setVolume(float volume) {
        if (player != null) {
            player.setVolume(Math.max(0f, Math.min(1f, volume)));
        }
    }

    /**
     * Mute stream
     */
    public void mute() {
        setVolume(0f);
    }

    /**
     * Unmute stream
     */
    public void unmute() {
        setVolume(1f);
    }

    /**
     * Release player resources
     */
    public void release() {
        if (player != null) {
            player.stop();
            player.release();
            player = null;
        }
    }
}

package com.adjaba.utilities;

import androidx.lifecycle.LiveData;
import androidx.lifecycle.MutableLiveData;

/**
 * Singleton manager for playlist sync events.
 * Replaces deprecated LocalBroadcastManager with LiveData pattern.
 * 
 * Usage:
 * - Workers call notifyPlaylistUpdated() to broadcast updates
 * - Activities observe getPlaylistUpdateLiveData() to receive updates
 */
public class PlaylistSyncManager {

    private static PlaylistSyncManager instance;
    private final MutableLiveData<PlaylistUpdate> playlistUpdateLiveData;

    private PlaylistSyncManager() {
        playlistUpdateLiveData = new MutableLiveData<>();
    }

    public static synchronized PlaylistSyncManager getInstance() {
        if (instance == null) {
            instance = new PlaylistSyncManager();
        }
        return instance;
    }

    /**
     * Notify observers that playlist has been updated
     * @param screenId The screen ID that was updated
     * @param adsCount Number of ads in updated playlist
     */
    public void notifyPlaylistUpdated(String screenId, int adsCount) {
        PlaylistUpdate update = new PlaylistUpdate(screenId, adsCount, System.currentTimeMillis());
        playlistUpdateLiveData.postValue(update);
        android.util.Log.i("PlaylistSyncManager", " Playlist update broadcast: screenId=" + screenId + ", adsCount=" + adsCount);
    }

    /**
     * Get LiveData for observing playlist updates
     * @return LiveData that emits PlaylistUpdate events
     */
    public LiveData<PlaylistUpdate> getPlaylistUpdateLiveData() {
        return playlistUpdateLiveData;
    }

    /**
     * Data class representing a playlist update event
     */
    public static class PlaylistUpdate {
        public final String screenId;
        public final int adsCount;
        public final long timestamp;

        public PlaylistUpdate(String screenId, int adsCount, long timestamp) {
            this.screenId = screenId;
            this.adsCount = adsCount;
            this.timestamp = timestamp;
        }
    }
}

package com.adjaba.workers;

import android.content.Context;
import android.content.Intent;
import android.content.SharedPreferences;
import android.os.Handler;
import android.os.Looper;

import androidx.annotation.NonNull;
import androidx.localbroadcastmanager.content.LocalBroadcastManager;
import androidx.work.Worker;
import androidx.work.WorkerParameters;

import com.adjaba.models.newmodels.WatchingModel;
import com.adjaba.room.AdDatabase;
import com.adjaba.room.AdEntity;
import com.adjaba.utilities.AuthManager;
import com.adjaba.utilities.AuthManager;
import com.adjaba.utilities.Config;
import com.adjaba.utilities.RetrofitBuilder;

import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

import okhttp3.OkHttpClient;
import okhttp3.Request;
import retrofit2.Call;
import retrofit2.Response;

/**
 * Background worker that periodically syncs the ad playlist with the backend.
 * - Compares backend playlist with local database
 * - Downloads new ads
 * - Deletes removed ads and their media files
 * - Handles offline gracefully (skips sync if network unavailable)
 * - Broadcasts update notification to AdvertWatching activity
 */
public class AdSyncWorker extends Worker {

    public static final String ACTION_PLAYLIST_UPDATED = "com.adjaba.PLAYLIST_UPDATED";
    public static final String EXTRA_SCREEN_ID = "screenId";
    public static final String EXTRA_ADS_COUNT = "adsCount";

    private static final String PREFS_NAME = "AdSyncPrefs";
    private static final String KEY_SCREEN_ID = "current_screen_id";

    public AdSyncWorker(@NonNull Context context, @NonNull WorkerParameters params) {
        super(context, params);
    }

    @NonNull
    @Override
    public Result doWork() {
        Context context = getApplicationContext();
        android.util.Log.i("AdSyncWorker", " Starting periodic ad sync...");

        // Get current screen ID from SharedPreferences
        SharedPreferences prefs = context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE);
        String screenId = prefs.getString(KEY_SCREEN_ID, null);

        if (screenId == null || screenId.isEmpty()) {
            android.util.Log.w("AdSyncWorker", "⚠️ No screen ID configured - skipping sync");
            return Result.success();
        }

        android.util.Log.i("AdSyncWorker", "   Screen ID: " + screenId);

        // Get auth token
        String token = AuthManager.getToken(context);
        if (token == null || token.isEmpty()) {
            android.util.Log.w("AdSyncWorker", "⚠️ No auth token - skipping sync");
            return Result.retry();
        }

        // Perform smart sync
        boolean syncSuccess = performSmartSync(context, screenId, token);

        return syncSuccess ? Result.success() : Result.retry();
    }

    /**
     * Performs differential sync between backend playlist and local database
     */
    private boolean performSmartSync(Context context, String screenId, String token) {
        try {
            AdDatabase db = AdDatabase.getInstance(context);

            // Get existing local ad IDs
            List<String> localAdIds = db.adDao().getAdIdsByScreen(screenId);
            android.util.Log.i("AdSyncWorker", " Local database has " + (localAdIds == null ? 0 : localAdIds.size()) + " ads");

            // Fetch backend playlist
            RetrofitBuilder retrofitBuilder = new RetrofitBuilder();
            String screenIdForApi = screenId.contains("/") ? screenId.split("/")[0] : screenId;

            Call<List<WatchingModel>> call = retrofitBuilder.apiCalls()
                    .getAdsByScreen(screenIdForApi, "Bearer " + token);

            Response<List<WatchingModel>> response = call.execute();

            if (!response.isSuccessful()) {
                if (response.code() == 401) {
                    android.util.Log.w("AdSyncWorker", "⚠️ 401 Unauthorized — refreshing token and retrying...");
                    String newToken = AuthManager.reAuthenticateSync(context);
                    if (newToken == null) {
                        android.util.Log.e("AdSyncWorker", "❌ Re-authentication failed — aborting sync");
                        return false;
                    }
                    // Retry the playlist call once with the fresh token
                    call = retrofitBuilder.apiCalls().getAdsByScreen(screenIdForApi, "Bearer " + newToken);
                    response = call.execute();
                    if (!response.isSuccessful()) {
                        android.util.Log.e("AdSyncWorker", "❌ API error after re-auth - response code: " + response.code());
                        return false;
                    }
                    android.util.Log.i("AdSyncWorker", "✅ Retry succeeded after token refresh");
                } else {
                    android.util.Log.e("AdSyncWorker", "❌ API error - response code: " + response.code());
                    return false;
                }
            }

            List<WatchingModel> backendAds = response.body();
            if (backendAds == null || backendAds.isEmpty()) {
                android.util.Log.i("AdSyncWorker", "⚠️ No ads in backend playlist - keeping local cache");
                return true;
            }

            android.util.Log.i("AdSyncWorker", " Backend has " + backendAds.size() + " ads");

            // Get backend ad IDs
            List<String> backendAdIds = new ArrayList<>();
            for (WatchingModel ad : backendAds) {
                backendAdIds.add(ad.adContractData.advertId);
            }

            // Determine NEW ads (in backend but not in local)
            List<String> newAdIds = new ArrayList<>();
            for (String backendId : backendAdIds) {
                if (!localAdIds.contains(backendId)) {
                    newAdIds.add(backendId);
                }
            }

            // Determine REMOVED ads (in local but not in backend)
            List<String> removedAdIds = new ArrayList<>();
            for (String localId : localAdIds) {
                if (!backendAdIds.contains(localId)) {
                    removedAdIds.add(localId);
                }
            }

            android.util.Log.i("AdSyncWorker", "    NEW ads to download: " + newAdIds.size());
            android.util.Log.i("AdSyncWorker", "   ️ REMOVED ads to delete: " + removedAdIds.size());
            android.util.Log.i("AdSyncWorker", "   ✅ EXISTING ads (keep): " + (localAdIds.size() - removedAdIds.size()));

            // Delete removed ads and their media files
            for (String removedId : removedAdIds) {
                AdEntity removedAd = db.adDao().getAdById(removedId);
                if (removedAd != null && removedAd.localPath != null) {
                    File mediaFile = new File(removedAd.localPath);
                    if (mediaFile.exists()) {
                        boolean deleted = mediaFile.delete();
                        android.util.Log.i("AdSyncWorker", "   ️ Deleted media file: " + mediaFile.getName() + " (success=" + deleted + ")");
                    }
                }
                db.adDao().deleteAdById(removedId);
                android.util.Log.i("AdSyncWorker", "   ️ Deleted ad from DB: " + removedId);
            }

            // Download new ads
            int downloadedCount = 0;
            for (WatchingModel ad : backendAds) {
                String advertId = ad.adContractData.advertId;

                // Skip ads already in local database
                if (!newAdIds.contains(advertId)) {
                    continue;
                }

                android.util.Log.d("AdSyncWorker", "   Downloading new ad: " + advertId);

                String videoUrl = ad.adContractData.videoUrl;
                if (videoUrl == null || videoUrl.isEmpty()) {
                    android.util.Log.w("AdSyncWorker", "  ⚠️ Ad " + advertId + " has empty path - skipping");
                    continue;
                }

                // Download media file
                String downloadUrl = Config.BASE_URL + "/media/" + videoUrl;
                String extension;
                try {
                    int dot = videoUrl.lastIndexOf('.');
                    extension = dot >= 0 ? videoUrl.substring(dot + 1) : "mp4";
                } catch (Exception e) {
                    extension = "mp4";
                }
                String fileName = UUID.randomUUID().toString() + "." + extension;

                String localPath = downloadFileWithAuth(context, downloadUrl, fileName, token);
                if (localPath != null) {
                    String mediaFormat = isVideo(videoUrl) ? "VIDEO" : "IMAGE";

                    AdEntity adEntity = new AdEntity(
                            advertId,
                            mediaFormat,
                            localPath,
                            ad.adContractData.textTop,
                            ad.adContractData.textBottom,
                            ad.adContractData.textLeft,
                            ad.adContractData.textRight,
                            ad.duration * 1000,
                            "Landscape",
                            screenId,
                            ad.contractId,
                            listToString(ad.adContractData.targetHours),
                            downloadedCount,
                            ad.currency,
                            ad.maxBid,
                            listStrToString(ad.adContractData.targetGender),
                            listStrToString(ad.adContractData.targetAgeGroup),
                            listStrToString(ad.adContractData.targetTags),
                            listStrToString(ad.adContractData.targetEmotion)
                    );

                    db.adDao().insertAd(adEntity);
                    downloadedCount++;
                    android.util.Log.d("AdSyncWorker", "  ✅ Downloaded and saved ad: " + advertId);
                }
            }

            android.util.Log.i("AdSyncWorker", "✅ Sync complete - downloaded " + downloadedCount + " new ads");

            // Broadcast update notification if changes were made
            if (downloadedCount > 0 || removedAdIds.size() > 0) {
                broadcastPlaylistUpdate(context, screenId, backendAds.size());
            }

            return true;

        } catch (Exception e) {
            android.util.Log.e("AdSyncWorker", "❌ Sync failed: " + e.getMessage(), e);
            return false;
        }
    }

    /**
     * Download file with authorization header
     */
    private String downloadFileWithAuth(Context context, String fileUrl, String fileName, String token) {
        OkHttpClient client = new OkHttpClient();
        Request.Builder builder = new Request.Builder().url(fileUrl);
        if (token != null) {
            builder.addHeader("Authorization", "Bearer " + token);
        }
        try (okhttp3.Response response = client.newCall(builder.build()).execute()) {
            if (response.isSuccessful() && response.body() != null) {
                InputStream inputStream = response.body().byteStream();
                File file = new File(context.getFilesDir(), fileName);
                FileOutputStream outputStream = new FileOutputStream(file);
                byte[] buffer = new byte[4096];
                int bytesRead;
                while ((bytesRead = inputStream.read(buffer)) != -1) {
                    outputStream.write(buffer, 0, bytesRead);
                }
                outputStream.close();
                inputStream.close();
                return file.getAbsolutePath();
            }
        } catch (IOException e) {
            android.util.Log.e("AdSyncWorker", "  ❌ Download error: " + e.getMessage());
        }
        return null;
    }

    /**
     * Broadcast playlist update notification to AdvertWatching activity
     */
    private void broadcastPlaylistUpdate(Context context, String screenId, int adsCount) {
        Intent intent = new Intent(ACTION_PLAYLIST_UPDATED);
        intent.putExtra(EXTRA_SCREEN_ID, screenId);
        intent.putExtra(EXTRA_ADS_COUNT, adsCount);
        LocalBroadcastManager.getInstance(context).sendBroadcast(intent);
        android.util.Log.i("AdSyncWorker", " Broadcasted playlist update notification");
    }

    /**
     * Check if file is a video based on extension
     */
    private boolean isVideo(String path) {
        if (path == null) return false;
        String lower = path.toLowerCase();
        return lower.endsWith(".mp4") || lower.endsWith(".avi") || lower.endsWith(".mkv") ||
                lower.endsWith(".webm") || lower.endsWith(".mov");
    }

    /**
     * Convert list of integers to slash-separated string
     */
    private String listToString(List<Integer> list) {
        if (list == null || list.isEmpty()) return "";
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < list.size(); i++) {
            sb.append(list.get(i));
            if (i != list.size() - 1) {
                sb.append("/");
            }
        }
        return sb.toString();
    }

    /** Convert a List<String> to a comma-separated string for DB storage. */
    private String listStrToString(List<String> list) {
        if (list == null || list.isEmpty()) return null;
        return android.text.TextUtils.join(",", list);
    }

    /**
     * Helper method to set current screen ID for background sync
     * Should be called from SelectScreens when Play is clicked
     */
    public static void setCurrentScreenId(Context context, String screenId) {
        SharedPreferences prefs = context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE);
        prefs.edit().putString(KEY_SCREEN_ID, screenId).apply();
        android.util.Log.i("AdSyncWorker", "✅ Set current screen ID for background sync: " + screenId);
    }
}

